#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxArea(vector<int>& height) {\n        int n = height.size();\n        int ans = 0;\n        for (int i = 0; i < n; ++i) {\n            for (int j = i + 1; j < n; ++j) {\n                int h = min(height[i], height[j]);\n                int w = j - i;\n                ans = max(ans, h * w);\n            }\n        }\n        return ans;\n    }\n};
